<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputError from '@/Components/InputError.vue';
import Modal from '@/Components/Modal.vue';
import ValidationSummary from '@/Components/ValidationSummary.vue';
import Badge from '@/Components/UI/Badge.vue';
import Button from '@/Components/UI/Button.vue';
import Card from '@/Components/UI/Card.vue';
import EmptyState from '@/Components/UI/EmptyState.vue';
import PageHeader from '@/Components/UI/PageHeader.vue';
import { invitationStatus, money, paymentStatus, statusTone } from '@/Support/AdminPresentation';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { reactive, ref } from 'vue';

const props = defineProps<{ customer: any; allowance: any; customerUsers: any[]; events: any[]; entitlements: any[]; packages: any[]; canAddSecondLogin: boolean }>();
const second = useForm({ name: '', email: '', password: '' });
const reset = useForm({ password: '' });
const newEntitlement = useForm({ event_package_id: props.packages[0]?.id ?? '', exact_guest_capacity: '' });
const entitlementForms = reactive(Object.fromEntries(props.entitlements.filter((entitlement: any) => entitlement.status === 'available').map((entitlement: any) => [entitlement.id, { event_package_id: entitlement.event_package_id, exact_guest_capacity: entitlement.exact_guest_capacity }])) as Record<number, { event_package_id: number; exact_guest_capacity: number }>);
const editingEntitlementId = ref<number | null>(null);
const resetUserId = ref<number | null>(null);
const showSecondLogin = ref(false);
const showAddInvitation = ref(false);
const resetPassword = (user: any) => reset.put(route('admin.customer-users.password.update', user.id), { onSuccess: () => { reset.reset(); resetUserId.value = null; } });
const startInvitation = (id: number) => router.post(route('admin.customers.invitations.start', props.customer.id), { entitlement_id: id });
const saveEntitlement = (id: number) => router.patch(route('admin.customers.invitation-entitlements.update', [props.customer.id, id]), entitlementForms[id], { preserveScroll: true, onSuccess: () => { editingEntitlementId.value = null; } });
const addEntitlement = () => newEntitlement.post(route('admin.customers.invitation-entitlements.store', props.customer.id), { preserveScroll: true, onSuccess: () => { newEntitlement.reset(); showAddInvitation.value = false; } });
const addSecondLogin = () => second.post(route('admin.customers.second-login.store', props.customer.id), { preserveScroll: true, onSuccess: () => { second.reset(); showSecondLogin.value = false; } });
const packageLabel = (plan: any) => `${plan.name} · $${Number(plan.price ?? 0).toFixed(2)}`;
const paymentTone = (event: any) => !event.finance?.has_record ? 'no_record' : event.finance.remaining_amount > 0 ? (event.finance.paid_amount > 0 ? 'partially_paid' : 'unpaid') : 'paid';
const linkedInvitation = (entitlement: any) => props.events.find((event: any) => event.id === entitlement.claimed_event_id);
const eventType = (value?: string | null) => value ? value.replaceAll('_', ' ') : 'Type not set';
</script>

<template>
  <Head :title="customer.name" />
  <AuthenticatedLayout>
    <template #header><PageHeader :title="customer.name" eyebrow="Client record" subtitle="Accounts, invitation entitlements, and invitation activity in one operational view."><template #actions><Link :href="route('admin.customers.index')" class="fe-btn fe-btn-ghost">Back to Clients</Link></template></PageHeader></template>
    <main class="fe-page fe-page-wide space-y-5">
      <section class="grid grid-cols-2 gap-2 sm:grid-cols-4 sm:gap-3" aria-label="Client invitation summary"><div class="rounded-xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface)] px-3 py-3 sm:px-4"><p class="text-[11px] font-bold uppercase tracking-[.14em] text-[color:var(--fe-text-muted)]">Allowed</p><p class="mt-1 text-xl font-semibold text-[color:var(--fe-text)]">{{ allowance.allowed_events }}</p></div><div class="rounded-xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface)] px-3 py-3 sm:px-4"><p class="text-[11px] font-bold uppercase tracking-[.14em] text-[color:var(--fe-text-muted)]">Used</p><p class="mt-1 text-xl font-semibold text-[color:var(--fe-text)]">{{ allowance.used_events }}</p></div><div class="rounded-xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface)] px-3 py-3 sm:px-4"><p class="text-[11px] font-bold uppercase tracking-[.14em] text-[color:var(--fe-text-muted)]">Available</p><p class="mt-1 text-xl font-semibold text-[color:var(--fe-text)]">{{ allowance.remaining_events }}</p></div><div class="rounded-xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface)] px-3 py-3 sm:px-4"><p class="text-[11px] font-bold uppercase tracking-[.14em] text-[color:var(--fe-text-muted)]">Primary login</p><p class="mt-1 truncate text-sm font-semibold text-[color:var(--fe-text)]">{{ customerUsers[0]?.email || 'Not assigned' }}</p></div></section>

      <section class="grid gap-5 lg:grid-cols-2">
        <Card :class="{ 'self-start': resetUserId !== null || showSecondLogin }"><div class="flex items-start justify-between gap-4"><div><p class="fe-page-eyebrow">Client</p><h2 class="fe-section-title mt-1">Client information</h2></div><span class="rounded-full bg-[color:var(--fe-surface-elevated)] px-2.5 py-1 text-xs text-[color:var(--fe-text-secondary)]">{{ customer.is_active ? 'Active account' : 'Inactive account' }}</span></div><dl class="mt-5 grid gap-4 text-sm sm:grid-cols-3"><div><dt class="text-xs font-bold uppercase tracking-[.12em] text-[color:var(--fe-text-muted)]">Contact</dt><dd class="mt-1 font-medium text-[color:var(--fe-text)]">{{ customer.contact_name || 'Not provided' }}</dd></div><div><dt class="text-xs font-bold uppercase tracking-[.12em] text-[color:var(--fe-text-muted)]">Email</dt><dd class="mt-1 break-words font-medium text-[color:var(--fe-text)]">{{ customer.email || 'No email' }}</dd></div><div><dt class="text-xs font-bold uppercase tracking-[.12em] text-[color:var(--fe-text-muted)]">Phone</dt><dd class="mt-1 font-medium text-[color:var(--fe-text)]">{{ customer.phone || 'No phone' }}</dd></div></dl></Card>

        <Card><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="fe-page-eyebrow">Access</p><h2 class="fe-section-title mt-1">Accounts</h2></div><Button v-if="canAddSecondLogin && !showSecondLogin" type="button" variant="secondary" @click="showSecondLogin = true">+ Add secondary login</Button></div><div v-if="customerUsers.length" class="mt-4 divide-y divide-[color:var(--fe-border)]"><article v-for="user in customerUsers" :key="user.id" class="py-3 first:pt-0 last:pb-0"><div class="flex flex-wrap items-center justify-between gap-3"><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><p class="font-semibold text-[color:var(--fe-text)]">{{ user.name }}</p><Badge :tone="user.customer_account_role === 'primary' ? 'accent' : 'neutral'">{{ user.customer_account_role }}</Badge></div><p class="mt-1 break-all text-sm text-[color:var(--fe-text-secondary)]">{{ user.email }}</p></div><Button type="button" variant="secondary" @click="resetUserId = resetUserId === user.id ? null : user.id">Reset password</Button></div><form v-if="resetUserId === user.id" class="mt-3 flex flex-wrap items-end gap-2 rounded-lg bg-[color:var(--fe-surface-elevated)] p-3" @submit.prevent="resetPassword(user)"><label class="min-w-52 flex-1 text-sm">Temporary password<input v-model="reset.password" type="password" required class="mt-1 w-full" /><InputError :message="reset.errors.password" /></label><Button type="submit" variant="secondary" :loading="reset.processing">Save password</Button><Button type="button" variant="ghost" @click="resetUserId = null; reset.reset(); reset.clearErrors()">Cancel</Button></form></article></div><EmptyState v-else class="mt-4" title="No client accounts yet." />
          <form v-if="canAddSecondLogin && showSecondLogin" class="mt-4 rounded-lg border border-dashed border-[color:var(--fe-border-strong)] bg-[color:var(--fe-surface-elevated)] p-3" @submit.prevent="addSecondLogin"><div class="flex items-center justify-between gap-3"><p class="text-sm font-semibold">Add secondary login</p><Button type="button" variant="ghost" @click="showSecondLogin = false; second.reset(); second.clearErrors()">Cancel</Button></div><div class="mt-3 grid gap-3 sm:grid-cols-3"><label class="text-sm">Name<input v-model="second.name" required class="mt-1 w-full" /><InputError :message="second.errors.name" /></label><label class="text-sm">Email<input v-model="second.email" type="email" required class="mt-1 w-full" /><InputError :message="second.errors.email" /></label><label class="text-sm">Temporary password<input v-model="second.password" type="password" required class="mt-1 w-full" /><InputError :message="second.errors.password" /></label></div><ValidationSummary :errors="second.errors" class="mt-3" /><div class="mt-3 flex justify-end"><Button type="submit" :loading="second.processing">Add secondary login</Button></div></form></Card>
      </section>

      <Card><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="fe-page-eyebrow">Purchased capacity</p><h2 class="fe-section-title mt-1">Invitation Entitlements</h2><p class="fe-section-copy">Available entitlements can be adjusted or started. Claimed entitlements preserve their purchased details.</p></div><Button type="button" @click="showAddInvitation = true">+ Add Invitation</Button></div><div v-if="entitlements.length" class="mt-5 divide-y divide-[color:var(--fe-border)]"><article v-for="(entitlement, index) in entitlements" :key="entitlement.id" class="py-5 first:pt-0 last:pb-0"><div class="grid gap-4 lg:grid-cols-[minmax(0,1fr)_auto]"><div><div class="flex flex-wrap items-center gap-2"><h3 class="font-semibold text-[color:var(--fe-text)]">Invitation #{{ index + 1 }}</h3><Badge :tone="entitlement.status === 'claimed' ? 'success' : 'accent'">{{ entitlement.status }}</Badge></div><div class="mt-3 grid gap-3 text-sm sm:grid-cols-3"><div><p class="text-xs font-bold uppercase tracking-[.12em] text-[color:var(--fe-text-muted)]">Package</p><p class="mt-1 font-medium">{{ entitlement.package?.name || 'Not assigned' }}</p></div><div><p class="text-xs font-bold uppercase tracking-[.12em] text-[color:var(--fe-text-muted)]">Guest capacity</p><p class="mt-1 font-medium">{{ entitlement.exact_guest_capacity }} guests</p></div><div v-if="entitlement.status === 'claimed'"><p class="text-xs font-bold uppercase tracking-[.12em] text-[color:var(--fe-text-muted)]">Linked invitation</p><p class="mt-1 font-medium">{{ linkedInvitation(entitlement)?.title || 'Invitation setup' }}</p></div></div><form v-if="entitlement.status === 'available' && editingEntitlementId === entitlement.id" class="mt-4 grid gap-3 rounded-lg bg-[color:var(--fe-surface-elevated)] p-3 sm:grid-cols-2" @submit.prevent="saveEntitlement(entitlement.id)"><label class="text-sm">Package<select v-model="entitlementForms[entitlement.id].event_package_id" class="mt-1 w-full"><option v-for="plan in packages" :key="plan.id" :value="plan.id">{{ packageLabel(plan) }}</option></select></label><label class="text-sm">Exact guest capacity<input v-model.number="entitlementForms[entitlement.id].exact_guest_capacity" type="number" min="1" class="mt-1 w-full" /></label><div class="sm:col-span-2 flex flex-wrap justify-end gap-2"><Button type="button" variant="ghost" @click="editingEntitlementId = null">Cancel</Button><Button type="submit" variant="secondary">Save changes</Button></div></form></div><div class="flex flex-wrap items-start gap-2 lg:justify-end"><template v-if="entitlement.status === 'claimed'"><Link v-if="linkedInvitation(entitlement)" :href="route('events.show', linkedInvitation(entitlement).id)" class="fe-btn fe-btn-secondary">View Invitation</Link></template><template v-else><Button type="button" variant="secondary" @click="editingEntitlementId = editingEntitlementId === entitlement.id ? null : entitlement.id">{{ editingEntitlementId === entitlement.id ? 'Close edit' : 'Edit' }}</Button><Button type="button" @click="startInvitation(entitlement.id)">Start Invitation</Button></template></div></div></article></div><EmptyState v-else class="mt-5" title="No invitation entitlements yet." message="Add an invitation entitlement to make a new invitation available for this client." /></Card>

      <Card><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="fe-page-eyebrow">Activity</p><h2 class="fe-section-title mt-1">Client Invitations</h2><p class="fe-section-copy">Invitation status, guest progress, and finance at a glance.</p></div><span class="rounded-full bg-[color:var(--fe-surface-elevated)] px-2.5 py-1 text-sm text-[color:var(--fe-text-secondary)]">{{ events.length }} total</span></div><div v-if="events.length" class="mt-5 space-y-3"><article v-for="event in events" :key="event.id" class="rounded-xl border border-[color:var(--fe-border)] p-4"><div class="flex flex-wrap items-start justify-between gap-4"><div class="min-w-0"><div class="flex flex-wrap items-center gap-2"><h3 class="font-semibold text-[color:var(--fe-text)]">{{ event.title || 'Invitation setup' }}</h3><Badge :tone="statusTone(event.invitation_status)">{{ invitationStatus(event.invitation_status) }}</Badge></div><p class="mt-1 text-sm capitalize text-[color:var(--fe-text-secondary)]">{{ eventType(event.event_type) }} · {{ event.date || 'Date not set' }}<span v-if="event.template_name"> · {{ event.template_name }}</span></p></div><div class="flex flex-wrap gap-2"><Link :href="route('events.show', event.id)" class="fe-btn fe-btn-secondary">View</Link><Link v-if="event.invitation_status !== 'archived'" :href="route('events.builder', event.id)" class="fe-btn fe-btn-secondary">Edit</Link></div></div><dl class="mt-4 grid grid-cols-2 gap-3 border-t border-[color:var(--fe-border)] pt-4 text-sm sm:grid-cols-5"><div><dt class="text-xs font-bold uppercase tracking-[.1em] text-[color:var(--fe-text-muted)]">Capacity</dt><dd class="mt-1 font-medium">{{ event.allocated_capacity }} / {{ event.guest_capacity || '—' }}</dd></div><div><dt class="text-xs font-bold uppercase tracking-[.1em] text-[color:var(--fe-text-muted)]">Families</dt><dd class="mt-1 font-medium">{{ event.responded_families_count }} / {{ event.families_count }}</dd></div><div><dt class="text-xs font-bold uppercase tracking-[.1em] text-[color:var(--fe-text-muted)]">Confirmed</dt><dd class="mt-1 font-medium">{{ event.confirmed_attendees }}</dd></div><div><dt class="text-xs font-bold uppercase tracking-[.1em] text-[color:var(--fe-text-muted)]">Finance</dt><dd class="mt-1 font-medium">{{ event.finance?.has_record ? paymentStatus(paymentTone(event)) : 'No financial record' }}</dd></div><div><dt class="text-xs font-bold uppercase tracking-[.1em] text-[color:var(--fe-text-muted)]">Outstanding</dt><dd class="mt-1 font-medium">{{ event.finance?.has_record ? money(event.finance.remaining_amount) : '—' }}</dd></div></dl></article></div><EmptyState v-else class="mt-5" title="No invitations yet." message="Start an invitation when the client has an available entitlement." /></Card>
    </main>

    <Modal :show="showAddInvitation" max-width="md" @close="showAddInvitation = false; newEntitlement.reset(); newEntitlement.clearErrors()"><form class="space-y-5 p-5 sm:p-6" @submit.prevent="addEntitlement"><div class="flex items-start justify-between gap-4"><div><p class="fe-page-eyebrow">Invitation entitlement</p><h2 class="fe-section-title mt-1">Add Invitation</h2><p class="fe-section-copy">Choose the purchased package and exact guest capacity for this invitation.</p></div><button type="button" class="rounded p-1 text-xl text-[color:var(--fe-text-muted)]" aria-label="Close" @click="showAddInvitation = false">×</button></div><div class="grid gap-4"><label>Package<select v-model="newEntitlement.event_package_id" class="mt-1 w-full"><option v-for="plan in packages" :key="plan.id" :value="plan.id">{{ packageLabel(plan) }}</option></select><InputError :message="newEntitlement.errors.event_package_id" /></label><label>Exact guest capacity<input v-model.number="newEntitlement.exact_guest_capacity" required type="number" min="1" class="mt-1 w-full" /><InputError :message="newEntitlement.errors.exact_guest_capacity" /></label></div><ValidationSummary :errors="newEntitlement.errors" /><div class="flex flex-wrap justify-end gap-3"><Button type="button" variant="ghost" @click="showAddInvitation = false; newEntitlement.reset(); newEntitlement.clearErrors()">Cancel</Button><Button type="submit" :loading="newEntitlement.processing">Add Invitation</Button></div></form></Modal>
  </AuthenticatedLayout>
</template>
